 status=503, reason=Service Unavailable 
 headers={'cache-control': 'no-cache', 'content-type': 'text/html'} 
 body=<!DOCTYPE html PUBLIC "-//W3C//DTD XHTML 1.0 Transitional//EN" "http://www.w3.org/TR/xhtml1/DTD/xhtml1-transitional.dtd">
<html xmlns="http://www.w3.org/1999/xhtml">
<head>
<meta http-equiv="Content-Type" content="text/html; charset=utf-8" />
<meta name="viewport" content="width=device-width,initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
<title>Error page</title>
<script src="//ajax.googleapis.com/ajax/libs/jquery/3.6.0/jquery.min.js"></script>
</head>
<style type="text/css" rel="stylesheet">
html,
body{
    height: 100%;
}
body{margin: 0;padding: 0;font-family: Arial, Helvetica, sans-serif;font-size: 13px;color: #111111;min-width: 300px;min-height: 200px;}
.content{
    background-color: #e5e6e7;
    height: 50%; display: flex;
}
.content .container{
width: 630px;
margin: 0 auto;
align-self: flex-end;
position: relative;
padding:0 240px 0 10px;
min-height: 305px;
box-sizing: border-box;
font-size: 16px;
}.content .container a{
color: #0024ff;
text-decoration: none;
}
.content .container h3{
font-size: 16px; color: #ff2f2f;
margin: 25px 0 0; font-weight: bold;
}
.content .container .content-box{
font-size: 16px; line-height: 22px; color: #666;
padding: 20px 22px; background-color: #fff; border-radius: 5px;
margin: 37px 0 25px;
}
.content .container p{
color: #666;
margin:0 0 10px;
padding: 0;
line-height: 1.1;
}
.content .container .error-img{
position: absolute; bottom: 0; right: 0;
z-index: 9;
}
.container-text{
    position: relative;
    z-index: 10;
}
@media (min-height:600px) {
    .content{
    min-height: 191px;
} 
}
@media (max-height:375px) {
    .content{
    height: 100%;
} 
}
@media (max-width:375px) {
    .content{
        height: 60%;
    }
    .content .container{
        padding-right: 140px;
    }
    .content .container .error-img{
right: -70px;
z-index: 9;
}
}
</style>
<body>
    <div class="content">
        <div class="container">
                <div class="container-text">
                <img src="https://logo.kiotviet.vn/KiotViet-Logo-Horizontal.svg" class="logo" alt="KiotViet" title="KiotViet" style="height: 32px;">
                <div class="content-box">Hiá»n táº¡i KiotViet Äang quÃ¡ táº£i vÃ  trong quÃ¡ trÃ¬nh xá»­ lÃ½. ChÃºng tÃ´i ráº¥t xin lá»i vá» sá»± báº¥t tiá»n nÃ y.</div>            
                <p>Báº¡n váº«n cÃ³ thá» tiáº¿p tá»¥c bÃ¡n hÃ ng <a href="/sale/#/">táº¡i ÄÃ¢y</a></p>
                <p style="font-size: 14px;">Hotline: 1900 6562 / Email: hotro@kiotviet.com</p>
                <h3>Lá»i 503</h3>
                </div>
            <img src="https://cdn-app.kiotviet.vn/img/error-person-503.png" class="error-img" alt="error img" title="error img">
        </div>
    </div>
</body>
<script type="text/javascript">
$(document).ready(function() {
    var strsess = localStorage.getItem('kvSession');
    var url = "#";
    var tagsale = $(".container p:first ");
    if (strsess) {
        var sess = JSON.parse(strsess);
        if (sess && sess.Retailer && sess.Retailer.Code) {
            if (sess.Retailer.IndustryId === 15) {
                url = "/" + sess.Retailer.Code + "/pos/#/cashier";
            } else {
                url = "/sale/#";
            }
            tagsale.find("a:first").attr("href", url);
            return;
        }
    }
    tagsale.hide();
});
</script></html>

